def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string must consist only of decimal digits.
    Raises ValueError for invalid inputs.
    """
    # Basic type and value checks
    if not isinstance(num_str, str):
        raise TypeError("num_str must be a string")
    if not isinstance(N, int) or not isinstance(K, int):
        raise TypeError("N and K must be integers")
    if len(num_str) != N:
        raise ValueError("Length of num_str does not match N")
    if N == 0:
        return 0
    if K < 0 or K > N - 1:
        raise ValueError("K must be between 0 and N-1 inclusive")
    if not num_str.isdigit():
        raise ValueError("num_str must contain only digits")

    # Special case: no multiplication signs
    if K == 0:
        return int(num_str)

    # Precompute integer values for all substrings num_str[i:j]
    val = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        num = 0
        for j in range(i, N):
            num = num * 10 + (ord(num_str[j]) - 48)
            val[i][j + 1] = num

    # DP table: dp[i][k] = max product for first i digits with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: k = 0
    for i in range(1, N + 1):
        dp[i][0] = val[0][i]

    # Fill DP
    for k in range(1, K + 1):
        # i must be at least k+1 to have k+1 parts
        for i in range(k + 1, N + 1):
            max_prod = 0
            # j is the split point: first part ends at j, second part starts at j
            # j must be at least k (since dp[j][k-1] requires at least k digits)
            for j in range(k, i):
                prod = dp[j][k - 1] * val[j][i]
                if prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    return dp[N][K]

