def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest
    common divisor (GCD) and y0 as their least common multiple (LCM).

    Args:
        x0 (int): The GCD that each pair (P, Q) must have.
        y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
        int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    # Validate inputs
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 < x0:
        return 0
    if y0 % x0 != 0:
        return 0

    # Helper function for gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    n = y0 // x0
    count = 0
    limit = int(n ** 0.5)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list):
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps or "NO ANSWER!" if impossible.
    """
